// xterm.js for the phone's terminal (BLG-42), bundled into the app so it works offline: no CDN,
// nothing fetched. The terminal screen runs it in a WebView (an iframe on the web), fed with the
// raw bytes of the Mac's PTY. Run after updating @xterm/xterm: `npm run terminal:bundle`.
// Also its font (BLG-108): JetBrains Mono (OFL-1.1, from @fontsource/jetbrains-mono), regular
// and bold, Latin and Latin Extended only (~60 KB), inlined as data URLs; other glyphs (box
// drawing, CJK) fall back to the system's monospace, which xterm.js fits to the cell.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
const pkg = path.dirname(require.resolve('@xterm/xterm/package.json'));
const version = JSON.parse(readFileSync(path.join(pkg, 'package.json'), 'utf8')).version;
// The UMD build (window.Terminal), without its source map comment.
const js = readFileSync(path.join(pkg, 'lib', 'xterm.js'), 'utf8').replace(/\n\/\/# sourceMappingURL=.*$/m, '');
const css = readFileSync(path.join(pkg, 'css', 'xterm.css'), 'utf8');
const out = path.join(here, '..', 'lib', 'terminal', 'xterm.generated.ts');
writeFileSync(
  out,
  `// Generated by scripts/bundle-terminal.mjs from @xterm/xterm ${version} (MIT, Copyright (c) The xterm.js authors). Do not edit.\n` +
    `/* eslint-disable */\nexport const XTERM_VERSION = ${JSON.stringify(version)};\nexport const XTERM_CSS = ${JSON.stringify(css)};\nexport const XTERM_JS = ${JSON.stringify(js)};\n`,
);

const fontPkg = path.dirname(require.resolve('@fontsource/jetbrains-mono/package.json'));
const fontVersion = JSON.parse(readFileSync(path.join(fontPkg, 'package.json'), 'utf8')).version;
const ranges = JSON.parse(readFileSync(path.join(fontPkg, 'unicode.json'), 'utf8'));
let fontCss = '';
for (const subset of ['latin', 'latin-ext']) {
  for (const weight of [400, 700]) {
    const b64 = readFileSync(path.join(fontPkg, 'files', `jetbrains-mono-${subset}-${weight}-normal.woff2`)).toString('base64');
    fontCss += `@font-face{font-family:'JetBrains Mono';font-style:normal;font-weight:${weight};font-display:block;src:url(data:font/woff2;base64,${b64}) format('woff2');unicode-range:${ranges[subset]}}\n`;
  }
}
const fontOut = path.join(here, '..', 'lib', 'terminal', 'font.generated.ts');
writeFileSync(
  fontOut,
  `// Generated by scripts/bundle-terminal.mjs from @fontsource/jetbrains-mono ${fontVersion} (SIL Open Font License 1.1, Copyright 2020 The JetBrains Mono Project Authors). Do not edit.\n` +
    `/* eslint-disable */\nexport const TERM_FONT_FAMILY = "JetBrains Mono";\nexport const TERM_FONT_CSS = ${JSON.stringify(fontCss)};\n`,
);
console.log(`wrote ${path.relative(process.cwd(), fontOut)} (JetBrains Mono ${fontVersion}, ${Math.round(fontCss.length / 1024)} KB)`);
console.log(`wrote ${path.relative(process.cwd(), out)} (xterm ${version}, ${Math.round((js.length + css.length) / 1024)} KB)`);
